   "class KerangkaAdaptif extends StatelessWidget {\n  const KerangkaAdaptif({super.key, required this.indeks, required this.pilih, required this.isi});\n  final int indeks;\n  final ValueChanged<int> pilih;\n  final Widget isi;\n\n  static const tujuan = [\n    (Icons.home, 'Beranda'),\n    (Icons.receipt_long, 'Pesanan'),\n    (Icons.person, 'Profil'),\n  ];\n\n  @override\n  Widget build(BuildContext context) {\n    final lebar = MediaQuery.sizeOf(context).width;\n    if (lebar < 600) {\n      return Scaffold(\n        body: isi,\n        bottomNavigationBar: NavigationBar(\n          selectedIndex: indeks,\n          onDestinationSelected: pilih,\n          destinations: [\n            for (final (ikon, label) in tujuan)\n              NavigationDestination(icon: Icon(ikon), label: label),\n          ],\n        ),\n      );\n    }\n    return Scaffold(\n      body: Row(children: [\n        NavigationRail(\n          extended: lebar >= 840,\n          selectedIndex: indeks,\n          onDestinationSelected: pilih,\n          destinations: [\n            for (final (ikon, label) in tujuan)\n              NavigationRailDestination(icon: Icon(ikon), label: Text(label)),\n          ],\n        ),\n        const VerticalDivider(width: 1),\n        Expanded(child: isi),\n      ]),\n    );\n  }\n}",
   None,
   so=[S('Buat widget yang menampilkan 2 kolom kartu di ponsel, 3 di tablet, dan 4 di layar lebar memakai LayoutBuilder.', 'Hitung jumlah kolom dari constraints.maxWidth.',
         "LayoutBuilder(\n  builder: (context, c) {\n    final kolom = c.maxWidth >= 1000 ? 4 : c.maxWidth >= 600 ? 3 : 2;\n    return GridView.count(\n      crossAxisCount: kolom,\n      children: [for (final p in produk) KartuProduk(p)],\n    );\n  },\n)"),
       S('Batasi lebar form login maksimal 420 px dan taruh di tengah layar lebar.', 'Center + ConstrainedBox(maxWidth: 420).',
         "Center(\n  child: ConstrainedBox(\n    constraints: const BoxConstraints(maxWidth: 420),\n    child: const FormLogin(),\n  ),\n)")],
   pts=['MediaQuery untuk ukuran layar, LayoutBuilder untuk ruang widget.', '< 600 NavigationBar, ≥ 600 NavigationRail.', 'Batasi lebar baca dengan ConstrainedBox.'],
